// N8N Code Node - Dynamic Chunking + Dynamic Batch Size (Fixed)
const items = $input.all();
const outputItems = [];

for (const item of items) {
  let fileName = '';
  let fileFound = false;
  let fileSize = 0;
  let binaryData = null;

  // Method 1: Check binary data written by the webhook
  if (item.binary && item.binary.file0 && item.binary.file0.fileName) {
    fileName = item.binary.file0.fileName;
    fileSize = item.binary.file0.fileSize || 0;
    binaryData = item.binary.file0;
    fileFound = true;
  }

  // Method 2: Try to extract from headers if multipart form data
  if (!fileFound && item.headers && item.headers['content-type']) {
    const contentType = item.headers['content-type'];
    if (contentType.includes('multipart/form-data')) {
      fileName = 'uploaded_file';
      fileFound = true;
    }
  }

  // Method 3: Check first available binary data
  if (!fileFound && item.binary) {
    const binaryKeys = Object.keys(item.binary);
    if (binaryKeys.length > 0) {
      const firstBinaryKey = binaryKeys[0];
      if (item.binary[firstBinaryKey].fileName) {
        fileName = item.binary[firstBinaryKey].fileName;
        fileSize = item.binary[firstBinaryKey].fileSize || 0;
        binaryData = item.binary[firstBinaryKey];
        fileFound = true;
      }
    }
  }

  // ===== DYNAMIC CHUNKING LOGIC =====
  let chunkSize, overlap;
  const fileSizeInMB = fileSize / (1024 * 1024);
  const fileExtension = fileName.split('.').pop()?.toLowerCase();

  // File size based chunking
  if (fileSizeInMB < 1) { // < 1MB
    chunkSize = 250;
    overlap = 50;
  } else if (fileSizeInMB < 5) { // 1-5MB
    chunkSize = 400;
    overlap = 80;
  } else if (fileSizeInMB < 15) { // 5-15MB
    chunkSize = 600;
    overlap = 120;
  } else if (fileSizeInMB < 50) { // 15-50MB
    chunkSize = 800;
    overlap = 160;
  } else { // > 50MB
    chunkSize = 1000;
    overlap = 200;
  }

  // File type based adjustment for chunks
  if (fileExtension === 'pdf') {
    chunkSize = Math.floor(chunkSize * 0.8);
  } else if (['txt', 'md'].includes(fileExtension)) {
    chunkSize = Math.floor(chunkSize * 1.2);
  }

  // Safety bounds for chunks
  chunkSize = Math.max(150, Math.min(chunkSize, 1200));
  overlap = Math.max(30, Math.min(overlap, chunkSize * 0.3));

  // ===== DYNAMIC BATCH SIZE LOGIC =====

  // Estimate total chunks
  const avgWordsPerPage = 300;
  const avgCharsPerWord = 5;
  const estimatedPages = Math.ceil(fileSizeInMB * 1000);
  const estimatedTotalChars = estimatedPages * avgWordsPerPage * avgCharsPerWord;
  const estimatedChunks = Math.ceil(estimatedTotalChars / chunkSize);

  let batchSize;
  let processingStrategy;

  // Batch size calculation based on file size and estimated chunks
  if (fileSizeInMB < 1) {
    batchSize = Math.min(25, Math.max(10, Math.ceil(estimatedChunks / 4)));
    processingStrategy = "small_file_precision";
  } else if (fileSizeInMB < 5) {
    batchSize = Math.min(75, Math.max(25, Math.ceil(estimatedChunks / 6)));
    processingStrategy = "medium_file_balanced";
  } else if (fileSizeInMB < 15) {
    batchSize = Math.min(150, Math.max(50, Math.ceil(estimatedChunks / 8)));
    processingStrategy = "large_file_efficient";
  } else if (fileSizeInMB < 50) {
    batchSize = Math.min(250, Math.max(100, Math.ceil(estimatedChunks / 10)));
    processingStrategy = "very_large_file_throughput";
  } else {
    batchSize = Math.min(400, Math.max(150, Math.ceil(estimatedChunks / 12)));
    processingStrategy = "huge_file_maximum";
  }

  // File type specific batch adjustments
  if (fileExtension === 'pdf') {
    batchSize = Math.floor(batchSize * 0.85);
  } else if (['docx', 'doc'].includes(fileExtension)) {
    batchSize = Math.floor(batchSize * 1.1);
  } else if (['txt', 'md'].includes(fileExtension)) {
    batchSize = Math.floor(batchSize * 1.2);
  }

  // API Rate limit considerations
  const isFreeTier = false; // Set this based on your OpenAI plan
  if (isFreeTier) {
    batchSize = Math.min(batchSize, 20);
  }

  // Final safety bounds for batch
  batchSize = Math.max(10, Math.min(batchSize, 500));

  // Calculate processing estimates
  const batchCount = Math.ceil(estimatedChunks / batchSize);
  const estimatedProcessingTime = batchCount * 2;

  // Delay calculation for rate limit management
  let delayBetweenBatches;
  if (fileSizeInMB > 20) {
    delayBetweenBatches = 500;
  } else if (fileSizeInMB > 5) {
    delayBetweenBatches = 300;
  } else {
    delayBetweenBatches = 100;
  }

  // Create output with all analysis
  outputItems.push({
    json: {
      ...item.json,

      // Original file info
      fileName: fileName,
      fileFound: fileFound,
      fileSize: fileSize,
      fileSizeInMB: parseFloat(fileSizeInMB.toFixed(2)),
      fileExtension: fileExtension,

      // Dynamic chunking parameters
      dynamicChunkSize: chunkSize,
      dynamicOverlap: overlap,

      // Dynamic batch processing parameters
      dynamicBatchSize: batchSize,
      delayBetweenBatches: delayBetweenBatches,
      processingStrategy: processingStrategy,

      // Estimates and analytics
      estimatedChunks: estimatedChunks,
      estimatedBatches: batchCount,
      estimatedProcessingTime: `${estimatedProcessingTime} seconds`,

      // Analysis metadata
      chunkingStrategy: `Size: ${fileSizeInMB.toFixed(1)}MB → Chunks: ${chunkSize}(${overlap}), Batches: ${batchSize}`,
      optimizationSummary: `${processingStrategy} - ${batchCount} batches of ${batchSize} items each`,

      // Technical details
      hasMultipartData: !!(item.headers && item.headers['content-type'] && item.headers['content-type'].includes('multipart')),
      binaryKeys: item.binary ? Object.keys(item.binary) : [],
      processedAt: new Date().toISOString()
    },
    binary: item.binary
  });
}

return outputItems;
